:root {
  /* Colors */
  --color-paper-canvas: #f6f6f3;
  --color-quartz-card: #ffffff;
  --color-stone-tile: #edede8;
  --color-pebble-button: #dbdbd2;
  --color-jet-action: #191919;
  --color-iron-ink: #060d25;
  --color-graphite-headline: #292929;
  --color-charcoal-ink: #353535;
  --color-slate-caption: #65656d;
  --color-ash-meta: #7a7d85;
  --color-mist-border: #e7e7e4;
  --color-orchid-glow: #cc85de;
  --color-sprout-pulse: #22c55e;

  /* Typography — Font Families */
  --font-switzer: "Switzer", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-system-ui: system-ui, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-ui-monospace: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.67;
  --tracking-small: 0.24px;
  --text-caption: 13px;
  --leading-caption: 1.54;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-subheading: 23px;
  --leading-subheading: 1.2;
  --tracking-subheading: -0.575px;
  --text-heading-sm: 27px;
  --leading-heading-sm: 1.3;
  --tracking-heading-sm: 0px;
  --text-heading: 32px;
  --leading-heading: 1.3;
  --tracking-heading: 0px;
  --text-heading-lg: 64px;
  --leading-heading-lg: 1.02;
  --tracking-heading-lg: -2.88px;
  --text-display: 104px;
  --leading-display: 1.04;
  --tracking-display: 0px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-9: 9px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-18: 18px;
  --spacing-22: 22px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-36: 36px;
  --spacing-48: 48px;
  --spacing-84: 84px;
  --spacing-96: 96px;

  /* Layout */
  --layout-max-width: 1128px;
  --layout-content-width: 1080px;
  --layout-showcase-width: 1040px;
  --layout-section-gap: 96px;
  --layout-section-gap-mobile: 48px;
  --layout-card-padding: 18px;
  --layout-element-gap: 12px;
  --layout-nav-height: 60px;
  --size-control-sm: 36px;
  --size-control: 40px;
  --size-control-lg: 48px;

  /* Border Radius */
  --radius-sm-2: 5px;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 20px;
  --radius-3xl: 23px;
  --radius-full: 200px;
  --radius-full-2: 999px;

  /* Named Radii */
  --radius-cards: 20px;
  --radius-small-cards: 16px;
  --radius-sections: 20px;
  --radius-buttons: 200px;
  --radius-pills: 200px;
  --radius-badges: 200px;
  --radius-tags: 999px;
  --radius-inputs: 23px;
  --radius-inner-tiles: 12px;
  --radius-small-elements: 10px;
  --radius-avatars: 6px;
  --radius-images: 50%;

  /* Shadows */
  --shadow-subtle: 0 1px 2px 0 rgba(16, 24, 40, 0.05);
  --shadow-subtle-2: inset 0 0 0 1px rgba(255, 255, 255, 0.7);
  --shadow-sm: inset 0 0 0 1px rgb(230, 230, 227), 0 1px 2px 0 rgba(6, 13, 37, 0.04);
  --shadow-sm-2: 0 0 0 2px rgb(255, 255, 255);
  --shadow-sm-3: inset 0 0 0 1.5px rgb(207, 207, 202);
  --shadow-md: 0 0 0 1px rgb(231, 231, 228), 0 2px 12px 0 rgba(6, 13, 37, 0.05);
  --shadow-md-2: 0 1px 2px 0 rgba(6, 13, 37, 0.04), 0 6px 18px 0 rgba(6, 13, 37, 0.05);
  --shadow-lg: 0 1px 2px 0 rgba(6, 13, 37, 0.06), 0 12px 40px -12px rgba(6, 13, 37, 0.28);

  /* Surfaces */
  --surface-paper-canvas: #f6f6f3;
  --surface-stone-tile: #edede8;
  --surface-quartz-card: #ffffff;
  --surface-jet-action: #191919;
}

